package io.vaultbridge.app;
import java.io.*;
import java.util.*;
import java.net.*;
import java.util.concurrent.atomic.AtomicBoolean;
import org.json.*;

public final class TransferTest {
    static int passed;
    static void check(boolean condition,String label){if(!condition)throw new AssertionError(label);passed++;System.out.println("PASS: "+label);}
    static void rejects(RunnableIO action,String label)throws Exception {boolean rejected=false;try{action.run();}catch(IOException e){rejected=true;}check(rejected,label);}
    interface RunnableIO{void run()throws Exception;}
    // A loopback relay deliberately cuts one TLS connection mid-block; no external traffic.
    static final class CutOnce implements AutoCloseable {
        final ServerSocket listener;final int target;final List<Socket> sockets=Collections.synchronizedList(new ArrayList<>());final AtomicBoolean cut=new AtomicBoolean();volatile boolean running=true;
        CutOnce(int targetPort)throws IOException{target=targetPort;listener=new ServerSocket(0,8,InetAddress.getByName("127.0.0.1"));Thread accept=new Thread(()->{while(running)try{Socket from=listener.accept(),to=new Socket("127.0.0.1",target);sockets.add(from);sockets.add(to);pump(from,to,false);pump(to,from,true);}catch(IOException e){if(running)throw new RuntimeException(e);}});accept.setDaemon(true);accept.start();}
        void pump(Socket source,Socket destination,boolean downstream){Thread thread=new Thread(()->{try{byte[] buffer=new byte[16384];int n,total=0;InputStream input=source.getInputStream();OutputStream output=destination.getOutputStream();while((n=input.read(buffer))!=-1){total+=n;if(downstream&&total>131072&&cut.compareAndSet(false,true)){source.close();destination.close();return;}output.write(buffer,0,n);output.flush();}}catch(IOException ignored){}finally{try{source.close();destination.close();}catch(IOException ignored){}}});thread.setDaemon(true);thread.start();}
        public void close()throws IOException{running=false;listener.close();synchronized(sockets){for(Socket socket:sockets)socket.close();}}
    }
    public static void main(String[] args)throws Exception {
        File workspace=new File(args[0]);String pairing=new BufferedReader(new InputStreamReader(System.in,"UTF-8")).readLine();JSONObject info=LanClient.parsePairing(pairing);LanClient lan=new LanClient(info.getString("host"),info.getInt("port"),info.getString("pin"),null);lan.pair(info.getString("code"),"Transfer JVM test");
        check(TransferEngine.count(TransferEngine.MAX_FILE)==2048,"Java accepts 8 GiB within bounded chunk count");rejects(()->TransferEngine.count(TransferEngine.MAX_FILE+1),"Java rejects oversized file");rejects(()->TransferEngine.path(".obsidian/config.json"),"Java rejects hidden notes configuration");rejects(()->TransferEngine.path("../escape.md"),"Java rejects path traversal");
        check(TransferEngine.alternate("README",1).equals("README (VaultBridge 1)"),"root file without extension receives valid alternate name");
        check(TransferEngine.alternate("note.md",2).equals("note (VaultBridge 2).md"),"root file extension is preserved in alternate name");
        check(TransferEngine.alternate("folder/README",3).equals("folder/README (VaultBridge 3)"),"nested extensionless file retains parent in alternate name");
        TransferClient client=new TransferClient(lan,s->{});JSONObject list=client.listing();JSONArray files=list.getJSONArray("files");check(files.length()==2,"generic list contains large file and raw ZIP");TransferEngine.validate(files);check(files.getJSONObject(0).getLong("size")>Engine.MAX_FILE,"network file exceeds old 256 MiB limit");
        JSONObject job=new JSONObject().put("id",UUID.randomUUID().toString().replace("-","")).put("offer",list.getString("id")).put("files",files);File folder=TransferEngine.folder(workspace,job.getString("id"));TransferEngine.save(folder,job);check(TransferEngine.load(folder).getString("offer").equals(list.getString("id")),"task snapshot persists for process restart");
        TransferClient[] first=new TransferClient[1];first[0]=new TransferClient(lan,s->{if(s.startsWith("接收"))first[0].pause();});rejects(()->first[0].download(job,folder,0),"download pauses after first verified network block");check(TransferEngine.verified(folder,0,0,TransferEngine.CHUNK,null)!=null,"paused download retains verified block");
        List<String> progress=new ArrayList<>();File downloaded;try(CutOnce relay=new CutOnce(lan.port)){LanClient proxied=new LanClient("127.0.0.1",relay.listener.getLocalPort(),lan.pin,lan.token);TransferClient reconnect=new TransferClient(proxied,progress::add);downloaded=reconnect.download(job,folder,0);check(relay.cut.get()&&progress.stream().anyMatch(s->s.startsWith("连接中断")),"real mid-block TLS disconnection retries and completes");}TransferClient resume=new TransferClient(lan,s->{});check(TransferEngine.hash(downloaded).equals(files.getJSONObject(0).getString("sha256")),"270 MiB download verifies whole-file SHA-256");check(progress.stream().filter(s->s.startsWith("接收")).findFirst().get().contains("分块 2/"),"resumed download skips already verified first block");
        File empty=resume.download(job,folder,1);check(empty.length()==0,"raw empty ZIP file saved without extraction");check(TransferEngine.assemble(folder,0,files.getJSONObject(0),null).equals(downloaded),"verified assembled file reused on retry");
        JSONObject note=lan.manifest().getJSONArray("files").getJSONObject(0);JSONObject noteJob=new JSONObject().put("mode","notes-download").put("files",new JSONArray().put(note));File notesFolder=TransferEngine.folder(workspace,UUID.randomUUID().toString().replace("-",""));File noteFile=resume.download(noteJob,notesFolder,0);check(TransferEngine.hash(noteFile).equals(note.getString("sha256")),"ordinary Obsidian pull also uses verified resumable chunk transport");
        JSONObject upload=new JSONObject().put("id",UUID.randomUUID().toString().replace("-","")).put("mode","notes").put("prefix","平板来件");File sendFolder=TransferEngine.folder(workspace,upload.getString("id"));File source=new File(sendFolder,"example.source");byte[] data=new byte[TransferEngine.CHUNK+99];new Random(12).nextBytes(data);try(FileOutputStream output=new FileOutputStream(source)){output.write(data);}JSONObject item=new JSONObject().put("path","平板笔记.md").put("size",source.length()).put("sha256",TransferEngine.hash(source)).put("local",source.getName());upload.put("files",new JSONArray().put(item));TransferEngine.save(sendFolder,upload);
        TransferClient[] sender=new TransferClient[1];sender[0]=new TransferClient(lan,s->{if(s.startsWith("发送"))sender[0].pause();});rejects(()->sender[0].upload(upload,sendFolder),"upload pauses after a durable remote block");new TransferClient(lan,s->{}).upload(upload,sendFolder);check(item.getBoolean("done"),"upload continues and marks only verified saved file done");check(item.getString("saved").startsWith("平板来件/"),"note upload honors selected vault subdirectory");check(TransferEngine.load(sendFolder).getJSONArray("files").getJSONObject(0).getBoolean("done"),"upload completion persists");
        check(!TransferEngine.retryable(new LanClient.RemoteError("identity changed")),"remote validation and authorization errors do not auto-retry");check(!TransferEngine.retryable(new TransferEngine.Paused()),"pause does not enter network retry loop");check(TransferEngine.retryable(new java.net.ConnectException()),"connection interruption permits bounded retry");check(Arrays.equals(TransferEngine.DELAYS,new int[]{2,4,8,15,30}),"network retry uses bounded backoff");
        check(!TransferEngine.retryable(new IOException("disk full")),"local storage errors do not enter network retry loop");
        File block=TransferEngine.verified(folder,0,0,TransferEngine.CHUNK,null);try(FileOutputStream output=new FileOutputStream(block)){output.write(0);}check(TransferEngine.verified(folder,0,0,TransferEngine.CHUNK,null)==null,"damaged persisted block requires re-download");
        LanClient forged=new LanClient(lan.host,lan.port,lan.pin,"forged");rejects(()->new TransferClient(forged,s->{}).listing(),"forged generic transfer authorization is rejected");
        System.out.println("Java transfer checks passed: "+passed);
    }
}
